\label{thm:main}
Let $R$ be a finite ai-semiring. If $S_7\in\mathsf V(R)$, then $R$ is
nonfinitely based. Consequently, $S_7$ is strongly nonfinitely based.

\label{lem:private}
Suppose that $D_E\neq\varnothing$ for every $E\in\mathcal E$. For every
nonempty commutative monomial $m$,
\begin{equation}\label{eq:rigidity}
S_7\models m\preccurlyeq p_{\mathcal E}
\quad\Longleftrightarrow\quad
m=m_E\text{ for some }E\in\mathcal E.
\end{equation}
Moreover, every point of $\bigcup\mathcal E$ belongs to an exact transversal
of $\mathcal E$.

\label{lem:stability}
Let $n,k\geq1$ and $\ell\geq0$ be integers. Let $\mathcal F$ be a finite
nonempty family of finite sets of variables such that
\begin{equation}\label{eq:intersection-condition}
|E|\geq k,\qquad |E\cap F|\leq\ell\quad(E\neq F),
\qquad k>(2^n-2)\ell.
\end{equation}
If $p$ is supported by $\mathcal F$ and $p\approx q$ follows from
$\operatorname{Id}_n(S_7)$ and the ai-semiring axioms, then $q$ is supported
by $\mathcal F$.

\label{lem:semilinear}
For every $b\in S$, the set $P_b$ is semilinear. Finite
representations of all these sets can be chosen together with
an integer $B\geq1$ such that every component
\eqref{eq:linear-set} in every representation satisfies
\begin{equation}\label{eq:B}
\lVert \mathbf b\rVert_1+\sum_{j=1}^q\lVert \mathbf v_j\rVert_1\leq B.
\end{equation}
The integer $B$ depends only on $S$.

\label{lem:probability}
Let $k\geq1$ be an integer, and put
\begin{equation}\label{eq:constants}
L=k+B,\qquad K=k+2B,\qquad C=rB,\qquad
c=\frac{1}{(2B+1)(4L)^K(K!)^r}.
\end{equation}
For every integer $N\geq4LK$, choose a random subset $E\subseteq[N]$ by first
choosing its size uniformly from $\{k,k+1,\ldots,K\}$ and then
choosing uniformly among subsets of that size. For every
assignment $\nu:[N]\to S$,
\begin{equation}\label{eq:probability}
\Pr\bigl(E\text{ realizes the full product of }\nu\bigr)
\geq cN^{-C}.
\end{equation}
In particular, the exponent $C$ is independent of $k$.

\label{lem:cover}
For every finite semigroup $S$ and every integer $n\geq1$,
there exist integers $N>K\geq k\geq1$ and $\ell\geq0$, and a
finite nonempty family $\mathcal F\subseteq\mathcal P([N])$, such that
\begin{enumerate}
\item $k\leq|E|\leq K$ for every $E\in\mathcal F$;
\item $|E\cap F|\leq\ell$ for distinct $E,F\in\mathcal F$, and
      $k>(2^n-2)\ell$;
\item for every assignment $\nu:[N]\to S$, some $E\in\mathcal F$
      realizes its full product.
\end{enumerate}

\label{prop:upward}
If $A$ is a finite ai-semiring with $S_7\in\mathsf V(A)$, then
$A$ is strongly nonfinitely based.

\label{cor:s7powers}
Both $\mathcal P^+(S_7,\cdot)$ and $\mathcal P(S_7,\cdot)$ are
strongly nonfinitely based.

\label{cor:groups}
Let $G$ be a finite group of order at least three. Then
both $\mathcal P^+(G)$ and $\mathcal P(G)$ are strongly nonfinitely based.
